CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, event TEXT NOT NULL, segment TEXT NOT NULL DEFAULT 'all', ref TEXT NOT NULL DEFAULT 'direct');
CREATE INDEX IF NOT EXISTS ix_events ON events(event,segment,ts);
CREATE TABLE IF NOT EXISTS signals (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, url TEXT NOT NULL UNIQUE, title TEXT NOT NULL, segment TEXT NOT NULL, seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_signals ON signals(segment);
CREATE TABLE IF NOT EXISTS job_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, job TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL);
